from review import card,save,DATE

def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d

def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

id='TCS-1930';_,c=card(id);refs=c['references'];refs[0]['locator']='CCC 2024, article 27: introduction, Hypotheses 9 and 10, Definition 1, and Open Question 2 on p. 27:14 read. The underlying target is PIH from W[1]≠FPT; the suggested proof technique is not part of the success criterion.'
refs.extend([dict(id='eth',title='Parameterized Inapproximability Hypothesis under ETH',authors='Venkatesan Guruswami, Bingkai Lin, Xuandi Ren, Yican Sun, Kewen Wu',year=2025,url='https://doi.org/10.1145/3749982',locator='Journal of the ACM, 2025; publisher statement of Hypothesis 1.1 and main ETH implication checked. Preprint arXiv:2311.16587 was first submitted in November 2023; this does not establish the W[1]≠FPT implication.'),dict(id='survey2026',title='Parameterized inapproximability: From Clique to PIH',authors='Yijia Chen, Bingkai Lin',year=2026,url='https://doi.org/10.1016/j.cosrev.2025.100834',locator='Computer Science Review 59, article 100834, February 2026. Full abstract and introduction checked: discusses PIH under ETH and explicitly distinguishes the still-open W[1]≠FPT target.')])
save(id,dict(title='Does W[1] ≠ FPT imply the Parameterized Inapproximability Hypothesis?',formal='Assuming W[1]≠FPT, is there an absolute constant ε∈(0,1) such that no deterministic fixed-parameter algorithm can distinguish a satisfiable binary constraint satisfaction instance on k variables from an instance in which every assignment violates at least an ε fraction of the constraints, with k as the parameter?',definitions='A binary constraint satisfaction instance has k variables, a finite alphabet Σ of size n, and explicitly given binary relations specifying the allowed pairs for constrained variable pairs. Its finite input length includes these relation tables. An assignment chooses one alphabet value for each variable; val(Π) is the maximum fraction of its constraints satisfied by an assignment. The promise is val(Π)=1 or val(Π)≤1−ε; no answer is prescribed for intermediate values. For an instance of encoded size L, fixed-parameter tractable means time f(k)L^C for some computable f and constant C independent of k and L. In the standard representation with one binary relation per constrained pair, this is equivalent to f(k)n^{O(1)} after absorbing polynomial k-factors into f. Here W[1]≠FPT is the standard deterministic hypothesis, equivalently that deciding whether a finite graph has a k-clique has no f(k)L^C algorithm. PIH asserts the existence of one fixed ε>0 for which the promised approximation task has no such algorithm, irrespective of the computable function f or constant exponent C. The question is the implication from exact parameterized hardness to that constant-gap hardness, not an unconditional assertion of W[1]≠FPT.',question_type='yes_no',answer_criterion='Establish the stated implication using only W[1]≠FPT as the complexity assumption, with a constant gap independent of k and n, or refute that implication. A result assuming ETH or Gap-ETH, a gap shrinking with k, or hardness for a list-assignment variant does not settle this target.',context_blocks=[b('Finding one violated constraint is weaker than finding many','Exact unsatisfiability only says every assignment fails somewhere. PIH asks for a constant fraction of failures on every assignment. If an instance has many constraints, the existence of just one unavoidable violation need not give any fixed gap.'),b('The parameter is the number of variables','The alphabet is allowed to grow with the input. Exhaustive search takes n^k time, whose exponent depends on k; that is not fixed-parameter tractable. A running time such as 2^{2^k}n^3 would qualify despite its very large dependence on k.'),b('The source proves Baby PIH under the desired assumption','Baby PIH distinguishes satisfiable instances from instances for which even a constant-size list of values at each variable cannot satisfy every constraint. This is a different guarantee from saying that every ordinary assignment violates a constant fraction of constraints.', 'primary'),b('ETH already implies PIH','The Guruswami–Lin–Ren–Sun–Wu theorem derives PIH from the Exponential Time Hypothesis. ETH imposes a quantitative subexponential-time obstruction for 3SAT and is a stronger assumption than the parameterized separation sought here. The February 2026 survey still separates these targets.', 'eth')],why='Would supply a parameterized analogue of the PCP theorem from the standard exact-hardness assumption, giving a common basis for constant-gap inapproximability across many parameterized optimization problems.',progress=[dict(date='2024',text='Baby PIH is established under W[1]≠FPT; the full PIH implication is left open.',citation='primary'),dict(date='2025',text='The journal version of PIH under ETH records the stronger-assumption theorem, whose preprint already appeared in 2023.',citation='eth'),dict(date='2026-02',text='The survey explicitly retains the distinction between PIH under ETH and PIH under W[1]≠FPT.',citation='survey2026')],references=refs,status='source_open',status_note='Source definitions, the ETH theorem and the February 2026 survey checked with later-result searches through 12 September 2026. No proof under only W[1]≠FPT was located.',model_self_contained=True,requires_context=False,importance=imp(c,'A general bridge from exact parameterized hardness to constant-gap approximation hardness.'),review_note='Recovered the constant-gap quantifiers, alphabet-size dependence and deterministic hypothesis. Removed the source’s suggested direct-product-testing route from the target, and separated the ETH result and Baby PIH from the desired implication.',working_summary=sm(['The hypothesis W[1]≠FPT says exact parameterized problems such as k-Clique do not admit fixed-parameter algorithms.','The question asks whether it also rules out distinguishing satisfiable binary constraint systems from systems that force a constant fraction of violations.','The parameter is the number of variables, while the alphabet may grow with the input.','PIH is already known under the stronger ETH assumption, and Baby PIH is known under W[1]≠FPT.','A proof of the full implication would provide a broad foundation for parameterized inapproximability.'],['primary','eth','survey2026'])),notes=['Restored the complete PIH implication and its constant-gap quantifiers.','Defined the parameter, representation and deterministic FPT convention.','Removed technique advice and distinguished Baby PIH and the ETH theorem.'],checked_sources=[r['url'] for r in refs])

id='TCS-1936';_,c=card(id);refs=c['references'];refs[0]['locator']='ITCS 2024, article 75: Definitions 10, 12, 20 and 33; Lemma 21; and Section 6/Open Problem 2 read. The displayed quantity is n/2, not n². This card spells out the black-box membership that defines TFAP for the corresponding circuit-input problem.'
save(id,dict(title='Does the n/2-Ramsey search problem belong to TFAP?',formal='Does the total search problem that, given adjacency-query access to a simple graph on 2^n vertices, asks for a clique or an independent set of size ⌊n/2⌋ belong to TFAP in the source’s black-box sense, namely the closure of robust total search problems under low-depth decision-tree many-one reductions?',definitions='Take n≥4, vertex set {0,1}^n and one input bit for each unordered pair of distinct vertices; let N=binom(2^n,2) be the number of these bits. A solution lists ⌊n/2⌋ distinct vertices and identifies whether all pairs are edges or all are nonedges. Each solution can be verified with O(n²)=poly(log N) queries. A black-box TFNP problem is a family R_N⊆{0,1}^N×O_N, with finite solution sets O_N, total on every input, and with a decision tree of depth poly(log N) verifying each proposed solution. A partial input a∈{0,1,*}^N is witnessing if some one output o is valid for every complete input extending a. A function h(N) is negligible in log N when, for every constant c>0, h(N)≤(log N)^{-c} for all sufficiently large N. A problem is robust if for every such nonnegative h, all sufficiently large N have the property that every partial input fixing at least (1−h(N))N bits is witnessing. A deterministic decision-tree many-one reduction R_N→Q_M has one depth-poly(log N) tree computing each target input bit and, for every target solution o, one such tree decoding a source solution; log M is poly(log N). For every source input x and every valid target solution o of the constructed target, decoding must give a valid source solution. No uniform circuit-construction condition is imposed on these decision trees. TFAP^dt consists precisely of problems reducible in this sense to a robust black-box TFNP problem. The source’s circuit-input TFAP definition assigns membership through this oracle counterpart: an explicit succinct adjacency circuit does not authorize a stronger, arbitrary white-box reduction. The floor fixes the harmless integer convention for the source’s n/2 notation.',question_type='yes_no',answer_criterion='Prove a low-depth decision-tree many-one reduction from this Ramsey search family to a robust total search family, with the required target-size bound and correctness for every target solution, or prove that no such reduction exists. Showing merely that every graph has many Ramsey sets, or proving membership for the smaller n/10 target, does not resolve this membership question.',context_blocks=[b('The graph is exponentially larger than a requested solution','The input describes 2^n vertices, but an answer contains only about n/2 of them. Ramsey’s theorem guarantees a clique or independent set of that size in every graph. Checking a proposed answer needs only its pairwise adjacency bits.'),b('Abundance means resilience of totality','A robust problem still has one definite valid answer after almost all input bits have been fixed, regardless of how the few missing bits are completed. This is stronger than counting many answers on each complete input: different completions could have entirely different valid sets.'),b('The Ramsey relation itself need not be robust','TFAP includes reductions to robust problems. Membership can therefore hold without proving that this particular adjacency-bit presentation has the robustness property. The reduction must preserve validity for every solution returned by the target.', 'primary'),b('Why this class matters','The source places weak pigeonhole search and several other abundant-solution tasks in TFAP and proves black-box separations from several standard TFNP subclasses. It conjectures Ramsey membership as a way to locate its totality principle more precisely.', 'primary'),b('The smaller target is a separate question','The source asks about n/10-Ramsey if n/2-Ramsey is not in TFAP. Finding a set of size n/10 is easier as an output requirement, so membership of that variant would not establish membership for the larger set requested here.', 'primary')],why='Would clarify whether Ramsey totality has the robustness underlying abundant-solution search classes, and sharpen the relationship between Ramsey search and pigeonhole-based TFNP principles.',progress=[dict(date='2024',text='The ITCS paper defines TFAP, proves its robustness/reduction characterization and poses n/2-Ramsey membership as Open Problem 2.',citation='primary')],references=refs,status='source_open',status_note='Exact Ramsey size, black-box definitions, white-box correspondence and later-result searches checked through 12 September 2026. No resolution of the n/2-Ramsey membership question was located.',model_self_contained=True,requires_context=False,importance=imp(c,'A structural classification of Ramsey search by robustness of totality.'),review_note='Corrected a broken fraction that read as n², recovered exponential graph size and the exact robustness quantifiers, and defined the reduction closure. Kept the n/10 variant and arbitrary white-box reductions outside the selected target.',working_summary=sm(['Every graph on 2^n vertices has a clique or independent set of about n/2 vertices.','The question asks whether finding one belongs to the abundant-solution class TFAP.','Robustness means a nearly complete partial input already forces one valid answer across all its completions.','TFAP permits low-depth reductions to robust problems, so the Ramsey presentation itself need not be robust.','The source’s separate n/10 question and its white-box closure conventions do not replace this black-box membership target.'],['primary'])),notes=['Restored n/2 rather than n² and defined the succinct Ramsey task.','Expanded negligible missing fractions, witnessing partial assignments and robust reduction closure.','Separated the source’s black-box membership from white-box closure and the n/10 variant.'],checked_sources=[refs[0]['url'],'https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.ITCS.2024.75'])
